/**
 * 组件库示例站注册表
 *
 * 集中维护每个 Re* 组件在「示例站」中的元信息：
 *  - name / title / category：模块分类、中文名
 *  - props：所有参数 + 示例值（每个参数都填了示例数据）
 *  - code：该示例的 Vue 源文件（实时代代码 Tab 展示 + 复制用）
 *  - example：示例文件（页面自动懒加载）
 *
 * 由 scripts/gen-docs-examples.mjs 生成，请勿手改。
 */
import type { Component } from 'vue';

/** 参数元信息 */
export interface DocProp {
  /** 参数名 */
  name: string;
  /** 参数类型 */
  type: 'string' | 'number' | 'boolean' | 'enum' | 'array' | 'object' | 'function' | 'component' | 'unknown' | 'other';
  /** 可选中值（enum 类型有值） */
  options: string[] | null;
  /** 默认值（原始文本） */
  default: string | null;
  /** 示例站采用的示例值 */
  example: string;
}

/** 组件注册条目 */
export interface DocComponent {
  /** 组件名（如 `ReButton`） */
  name: string;
  /** 中文名称 */
  title: string;
  /** 分类 */
  category: '基础' | '反馈' | '数据' | '编辑' | '展示' | '媒体' | '主题';
  /** 参数列表 */
  props: Record<string, DocProp>;
  /** 该示例在「实时代代码」Tab 显示的完整 Vue 源码 */
  code: string;
  /** 示例组件，懒加载 */
  example: () => Promise<Component>;
}

/** 分类 -> 中文分类名 */
export const DOC_CATEGORY_MAP: Record<string, string> = {
  基础: '基础控件',
  反馈: '反馈/加载',
  数据: '数据展示',
  编辑: '编辑/表单',
  展示: '展示卡片',
  媒体: '媒体/特效',
  主题: '主题/布局',
};

